        ', vyřídíme nejpozději do ' => ', vybavíme najneskôr do ',
        'Reklamace vyřízena' => 'Reklamácia vybavená',
        'Reklamace uznána zčásti ' => 'Reklamácia uznaná čiastočne ',
        'Reklamace uznána ' => 'Reklamácia uznaná ',
        'Reklamace zamítnuta ' => 'Reklamácia zamietnutá ',
        'Reklamace ' => 'Reklamácia ',
        'Předčasné ukončení: ' => 'Predčasné ukončenie: ',
        'Vrátili jsme nevyužité měsíce' => 'Vrátili sme nevyužité mesiace',
        ' za nevyužité celé měsíce služby ' => ' za nevyužité celé mesiace služby ',
        ' je na dobropisu.' => ' je na dobropise.',
        ' skončí za ' => ' skončí o ',
        'Nebude prodloužena, končí ' => 'Nebude predĺžená, končí ',
        '. Chcete-li ji zachovat, zapněte automatické prodloužení.' => '. Ak si ju chcete ponechať, zapnite automatické predĺženie.',
    ];

    /**
     * W5-5: Slovak gets its own branch only while config('onhost.locale_sk') is on; off, 'sk' (which CatalogController and
     * CartController can still read from the query) keeps every pre-W5-5 output byte for byte. Never decides currency, price or tax.
     */
    public static function slovak(string $locale): bool
    {
        return $locale === 'sk' && (bool) config('onhost.locale_sk', false);
    }

    public static function translate(?string $text, string $locale): ?string
    {
        if ($text === null || $text === '' || $locale === 'cs' || ($locale === 'sk' && ! self::slovak($locale))) {
            return $text;
        }
        $table = self::table($locale);
        if ($table === []) {
            return $text;
        }

        return strtr($text, $table); // strtr tries the longest keys first and never re-scans replaced text
    }

    /** Czech fragments (words with diacritics) a translated text still carries — the test's yardstick for coverage. @return list<string> */
    public static function untranslated(string $text): array
    {
        preg_match_all('/\p{L}*[ěščřžýáíéúůťďňĚŠČŘŽÝÁÍÉÚŮŤĎŇ]\p{L}*/u', $text, $m);

        return array_values(array_diff(array_unique($m[0]), ['Kč'])); // the currency symbol is a value, not a phrase
    }

    /** @return array<string,string> */
    private static function table(string $locale): array
    {
        return match ($locale) {
            'en' => self::EN,
            'sk' => self::SK, // reached only while Lexicon::slovak() is true, see translate()
            default => [],
        };
    }
}
